Aquí está un ejemplo de una función que realiza la conversión de texto Markdown a HTML en C++, utilizando la biblioteca Puglito:

```cpp
#include <iostream>
#include <string>
#include <pugixml.hpp>

using namespace std;

// función de conversión de Markdown a HTML
string convertMarkdownToHtml(const string& markdown) {
    pugi::xml_document doc;
    pugi::xml_parse_result result = doc.load_string(markdown.c_str());

    if (!result) {
        throw runtime_error("Error parsing Markdown: " + result.description());
    }

    // Crear un documento HTML
    pugi::xml_document htmlDoc;
    pugi::xml_node html = htmlDoc.append_child(pugi::node_element);
    html.append_attribute("lang") = "en";
    html.set_name("html");
    pugi::xml_node head = html.append_child(pugi::node_element);
    head.append_attribute("xmlns") = "http://www.w3.org/1999/xhtml";
    head.set_name("head");
    pugi::xml_node title = head.append_child(pugi::node_element);
    title.set_name("title");
    title.append_child().set_pcdata("Convertido de Markdown a HTML");

    pugi::xml_node body = html.append_child(pugi::node_element);
    body.set_name("body");

    // Convertir el documento de Markdown a HTML
    pugi::xml_node markdownNode = doc.first_child();
    convertMarkdownToHtmlRecursive(markdownNode, body);

    // Generar el documento HTML como cadena de texto
    string htmlString;
    pugi::xml_save_file(htmlDoc, htmlString.c_str(), pugi::format_html);
    return htmlString;
}

// Recursión para convertir el nodo de Markdown a HTML
void convertMarkdownToHtmlRecursive(pugi::xml_node node, pugi::xml_node& htmlBody) {
    if (!node) {
        return;
    }

    string tagName = node.name();
    if (tagName == "p") {
        pugi::xml_node textNode = node.child("text");
        if (textNode) {
            string text = textNode.text().as_string();
            htmlBody.append_child(pugi::node_element).append_attribute("class") = "markdown-body";
            htmlBody.last_child().set_content(pugi::node_pcdata, text.c_str());
        }
    } else if (tagName == "h1" || tagName == "h2" || tagName == "h3" || tagName == "h4" || tagName == "h5" || tagName == "h6") {
        string headerLevel = tagName.substr(1);
        pugi::xml_node textNode = node.child("text");
        if (textNode) {
            string text = textNode.text().as_string();
            htmlBody.append_child(pugi::node_element).append_attribute("class") = "markdown-body";
            htmlBody.last_child().set_name("h" + headerLevel);
            htmlBody.last_child().append_child().set_content(pugi::node_pcdata, text.c_str());
        }
    } else if (tagName == "ul" || tagName == "ol") {
        pugi::xml_node itemsNode = node.child(tagName.c_str());
        if (itemsNode) {
            pugi::xml_node itemNode;
            for (itemNode = itemsNode.first_child(); itemNode; itemNode = itemNode.next_sibling()) {
                pugi::xml_node textNode = itemNode.child("text");
                if (textNode) {
                    string text = textNode.text().as_string();
                    htmlBody.append_child(pugi::node_element).set_name(tagName.c_str());
                    htmlBody.last_child().append_child(pugi::node_element).set_name("li");
                    htmlBody.last_child().last_child().append_child().set_content(pugi::node_pcdata, text.c_str());
                }
            }
        }
    } else if (tagName == "a") {
        pugi::xml_node textNode = node.child("text");
        if (textNode) {
            string text = textNode.text().as_string();
            string href = node.attribute("href").value().c_str();
            htmlBody.append_child(pugi::node_element).append_attribute("class") = "markdown-body";
            htmlBody.last_child().set_name("a");
            htmlBody.last_child().append_attribute("href") = href.c_str();
            htmlBody.last_child().append_child().set_content(pugi::node_pcdata, text.c_str());
        }
    } else if (tagName == "img") {
        pugi::xml_node attributesNode = node.child("attributes");
        if (attributesNode) {
            pugi::xml_node srcNode = attributesNode.child("src");
            pugi::xml_node altNode = attributesNode.child("alt");
            string src = srcNode.text().as_string();
            string alt = altNode.text().as_string();
            htmlBody.append_child(pugi::node_element).set_name("img");
            htmlBody.last_child().append_attribute("src") = src.c_str();
            htmlBody.last_child().append_attribute("alt") = alt.c_str();
        }
    }

    for (pugi::xml_node childNode = node.first_child(); childNode; childNode = childNode.next_sibling()) {
        convertMarkdownToHtmlRecursive(childNode, htmlBody);
    }
}

int main() {
    string markdown = "Este es un **ejemplo** de texto con #encabezados, *negritas*, _cursivas_, ~tachado~ y ~subrayado~. También hay [enlaces](https://www.google.com/) y imágenes: ! [Logo de Google](https://www.google.com/images/branding/googlelogo/1x/googlelogo_color_272x92dp.png) ";
    string html = convertMarkdownToHtml(markdown);
    cout << "Markdown:\n" << markdown << "\n\n";
    cout << "HTML:\n" << html << "\n";
    return 0;
}
```

Este ejemplo usa Puglito, una biblioteca de parseo de XML ligera, para convertir el documento de entrada de Markdown en un árbol de nodos XML. Luego, se recorre el árbol de nodos y se convierte en un documento HTML usando la API de Puglito.

Este ejemplo no es exhaustivo y no cubre todas las posibles características de Markdown, pero proporciona una base para comenzar a desarrollar un conversor de Markdown a HTML personalizado. Se pueden agregar más características de Markdown y estilos HTML en función de las necesidades específicas de su aplicación.

